<script>
  // This is the Svelte twin of packages/astro/components/SVG/Displace.astro.
  // Same component, same props, same output — one for each framework. Keep them in sync.

  import { displaceSettings } from '@splendidlabz/utils'

  let {
    class: klass = '',
    preset = 'wet-ink',
    type,
    frequency,
    octaves,
    scale,
    seed,
    animate = false,
    duration,
    margin = 30,
    children,
    ...rest
  } = $props()

  // Warps its children by reading a noise field as a per-pixel x/y offset.
  // Unlike Noise, the noise is never drawn — only the displacement it produces.
  //
  // preset — supplies defaults for everything below.
  //   wet-ink, letterpress, heat-haze, bad-tape, shred
  //
  // frequency — wavelength of the distortion, roughly (1 / frequency) px.
  //   Pass [x, y] for directional distortion.
  //
  // scale — how far each pixel moves. Keep it under a quarter of the
  //   wavelength to warp rather than shred.
  //
  // animate — emits SMIL, so it runs with no JS. Only does anything on
  //   presets carrying animateTo.
  //
  // margin — filter region expansion in %. Too low and displaced pixels clip.

  // Displacement has to hit real DOM, so unlike Noise it can't inline itself
  // as a data URI — every instance needs its own filter id in the document.
  const uid = $props.id()
  const id = `displace-${uid}`

  const fx = $derived(
    displaceSettings({ preset, type, frequency, octaves, scale, seed, duration }),
  )

  const offset = $derived(-margin)
  const size = $derived(100 + margin * 2)
</script>

<span style:filter={`url(#${id})`} class="displace {klass}" {...rest}>
  {@render children?.()}
</span>

<svg class="displace-defs" aria-hidden="true" focusable="false">
  <filter
    {id}
    color-interpolation-filters="sRGB"
    height="{size}%"
    width="{size}%"
    x="{offset}%"
    y="{offset}%"
  >
    <feTurbulence
      baseFrequency={fx.frequency}
      numOctaves={fx.octaves}
      result="noise"
      seed={fx.seed}
      type={fx.type}
    >
      {#if animate && fx.animateTo}
        <animate
          attributeName="baseFrequency"
          dur="{fx.duration}s"
          repeatCount="indefinite"
          values="{fx.frequency};{fx.animateTo};{fx.frequency}"
        />
      {/if}
    </feTurbulence>
    <feDisplacementMap
      in="SourceGraphic"
      in2="noise"
      scale={fx.scale}
      xChannelSelector="R"
      yChannelSelector="G"
    />
  </filter>
</svg>

<style>
  .displace {
    display: inline-block;
  }

  .displace-defs {
    position: absolute;
    width: 0;
    height: 0;
    overflow: hidden;
  }
</style>
